INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_xian-cumin-lamb-stir-fry_v1', 7, 'garlic', 'garlic', 'garlic', 4, 'clove', '4 clove', NULL, 'sliced', 0, 'main');
