INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_xian-cumin-lamb-stir-fry_v1', 9, 'scallions', 'scallions', 'scallions', 4, 'count', '4 count', NULL, 'cut into 2-inch lengths', 0, 'main');
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_xian-cumin-lamb-stir-fry_v1', 10, 'cilantro', 'cilantro', 'cilantro', 0.5, 'cup', '0.5 cup', NULL, 'roughly chopped', 0, 'garnish');
INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_xian-cumin-lamb-stir-fry_v1', 11, 'jasmine-rice', 'jasmine rice', 'jasmine rice', 1.5, 'cup', '1.5 cup', NULL, 'rinsed', 0, 'main');
