INSERT INTO catalog_ingredient (recipe_version_id, position, ingredient_id, name, display_name, quantity, unit, raw_quantity, note, preparation, optional, role) VALUES ('rv_xian-cumin-lamb-stir-fry_v1', 13, 'neutral-oil', 'neutral oil', 'neutral oil', 3, 'tbsp', '3 tbsp', NULL, NULL, 0, 'fat');
