INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_citrus-fennel-arctic-char_v2', 'rcp_citrus-fennel-arctic-char', 'citrus-fennel-arctic-char', 2, 'Citrus Fennel Arctic Char', 'Roasted arctic char on sheet-pan fennel, finished with fresh dill and orange zest and juice.', 4, 15, 27, 42, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'none', 'Thickest part just opaque, flakes with a fork, 140-145 F. Not chalky. Fennel edges softened and starting to brown.', '["roast"]', '["dairy-free"]', '{"butter":"Do not swap the olive oil for butter. That would drop the dairy-free claim.","lemon":"Do not swap the orange for lemon. The citrus in this dish is orange."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '49dc99220a2e78675387e8ef81e9be63fb02c9685a54bbd309666cea407c3847', 'flavorweave-legacy-catalog-package', 'catalog/citrus-fennel-arctic-char/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_classic-smash-burgers_v1', 'rcp_classic-smash-burgers', 'classic-smash-burgers', 1, 'Classic Smash Burgers with Special Sauce', 'Double smash burgers: loose balls of 80/20 ground chuck pressed thin onto a ripping-hot cast-iron skillet for lacy, deeply browned edges, stacked with melted American cheese on butter-toasted sesame buns with a tangy pickle special sauce, dill pickles, paper-thin onion, and shredded iceberg.', 4, 10, 21, 31, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-high cast iron, very hot before the first smash. No oven.', 'Patties 1/4 inch thin with lacy, deep-brown crusted edges, cooked through to no more than a trace of pink (ground beef safe target 160°F). Cheese fully melted and draped. Buns golden on the cut side. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"special-sauce","name":"pickle special sauce","made_in_recipe":true,"store_bought":false,"ingredients":["mayonnaise","ketchup","yellow mustard","chopped dill pickles","pickle brine","garlic powder","black pepper"]},{"component_id":"double-smash-patties","name":"double smash patties with American cheese","made_in_recipe":true,"store_bought":false,"ingredients":["80/20 ground chuck","American cheese","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '666724ec16022eebef4eb2a04e1b5498c83439d7d3c4f15410cffcce4162445b', 'flavorweave-catalog-package', 'catalog/classic-smash-burgers/v1.json', '2026-10-04T00:00:00.000Z');
