INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_colombian-ajiaco_v1', 'rcp_colombian-ajiaco', 'colombian-ajiaco', 1, 'Colombian Ajiaco Chicken and Three-Potato Soup', 'Bogota''s comforting chicken soup: chicken thighs simmered with three kinds of potatoes until the russets melt and thicken the broth, with corn on the cob and dried guascas herb, finished with sour cream, capers, and avocado.', 4, 15, 67, 82, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High to bring to a boil, then medium-low simmer throughout.', 'Chicken 175 F and shreddable. Russets dissolved into the broth; yellow and red potatoes tender but intact. Corn tender.', '["simmer"]', '[]', 'null', '[{"component_id":"soup","name":"chicken and potato soup","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","russet potatoes","yukon gold potatoes","red potatoes","corn","guascas","scallions","garlic","chicken stock","water","salt"]},{"component_id":"toppings","name":"toppings","made_in_recipe":true,"store_bought":false,"ingredients":["sour cream","capers","avocado","cilantro"]}]', 'published', 'draft', 'global', NULL, 'dd11a55fdfa021017b1d583998a0c8e32f16ab82b3e28403b0437129fb36c5e9', 'flavorweave-catalog-package', 'catalog/colombian-ajiaco/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_cottage-pie_v1', 'rcp_cottage-pie', 'cottage-pie', 1, 'Cottage Pie with Thyme Gravy', 'Ground beef simmered with onion, carrot, celery, and peas in a glossy thyme gravy, topped with buttery mashed potatoes raked into ridges and baked until the peaks are golden and crisp.', 4, 15, 66, 81, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'High to boil the potatoes, then a simmer; medium-high to brown the beef, medium for vegetables and gravy; oven 400 F, then broil.', 'Gravy glossy and coating a spoon; bubbling at the edges after baking. Mash ridges golden-brown and crisp. Beef cooked through (160 F). kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"beef-thyme-filling","name":"beef and vegetables in thyme gravy","made_in_recipe":true,"store_bought":false,"ingredients":["ground beef","neutral oil","yellow onion","carrots","celery","garlic","tomato paste","flour","beef broth","Worcestershire sauce","fresh thyme","bay leaf","black pepper","frozen peas"]},{"component_id":"buttery-mash","name":"buttery mashed potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["Yukon Gold potatoes","kosher salt","unsalted butter","whole milk"]}]', 'published', 'draft', 'global', NULL, '462722d0e6be0b42ae636fe460a1c068d17670083f92aef3ff763bd202df26ce', 'flavorweave-catalog-package', 'catalog/cottage-pie/v1.json', '2026-10-04T00:00:00.000Z');
