INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_crispy-fish-tacos-cabbage-slaw_v2', 'rcp_crispy-fish-tacos-cabbage-slaw', 'crispy-fish-tacos-cabbage-slaw', 2, 'Crispy Fish Tacos with Cabbage Slaw', 'Cornmeal-crusted pan-fried cod in corn tortillas with a cabbage-carrot slaw and dairy-free crema.', 4, 15, 20, 35, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'none', 'Crust golden. Cod opaque, flakes easily, 145 F in the center of a strip. Not chalky.', '["stovetop"]', '["dairy-free"]', '{"crema":"Store-bought dairy-free crema, or 1/2 cup vegan mayo plus the juice of 1/2 lime. Do not use sour cream or yogurt.","soy":"Some vegan mayos and dairy-free cremas contain soy. Soy is not a confirmed allergen until the brand is known."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '788a4b6967f46cef0c427303d4039e174e2516f0c2dbd694705ade27c7a81c7d', 'flavorweave-legacy-catalog-package', 'catalog/crispy-fish-tacos-cabbage-slaw/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_crispy-skillet-chicken-sandwiches_v1', 'rcp_crispy-skillet-chicken-sandwiches', 'crispy-skillet-chicken-sandwiches', 1, 'Crispy Skillet Chicken Sandwiches', 'Pound-thin chicken cutlets seared in a skillet and stacked on rolls with lemon-dijon mayonnaise, lettuce, and tomato.', 4, 12, 16, 28, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Skillet over medium-high; lower to medium only if the crust darkens before the center is done.', '165°F in the center of each cutlet. Color is not the doneness test.', '[]', '[]', 'null', '[{"component_id":"lemon-dijon-mayonnaise","name":"lemon-dijon mayonnaise","made_in_recipe":true,"store_bought":false,"built_from_store_bought":["mayonnaise","dijon mustard"],"ingredients":["mayonnaise","dijon mustard","lemon","fresh parsley","garlic","kosher salt"]}]', 'published', 'draft', 'global', NULL, '845ddd91f0433d50736f66950ad5f007376ec3a236ac97dcf273a9803d383dc7', 'flavorweave-catalog-package', 'catalog/crispy-skillet-chicken-sandwiches/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_deep-fried-cod-roasted-potatoes_v1', 'rcp_deep-fried-cod-roasted-potatoes', 'deep-fried-cod-roasted-potatoes', 1, 'Deep-Fried Cod with Oven-Roasted Potatoes', 'Cod in a club-soda batter, deep-fried until golden, with oven-roasted potato wedges whose edges are crisp. Lemon, parsley, and vinegar at the table. No butter.', 4, 20, 35, 55, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Oven 425 F for the potatoes. Oil at 375 F for the cod.', 'Potatoes tender in the center with crisp edges. Cod deep golden, opaque, and 145 F in the center.', '["deep-fry","roast"]', '[]', 'null', '[{"component_id":"batter","name":"club-soda batter","made_in_recipe":true,"store_bought":false,"ingredients":["flour","cornstarch","baking powder","egg","club soda"]},{"component_id":"potatoes","name":"oven-roasted potato wedges","made_in_recipe":true,"store_bought":false,"ingredients":["russet potatoes","olive oil"]}]', 'published', 'draft', 'global', NULL, 'b8fe2bd170a58627f3880eb53002d90e0f3074f993bd3cf9afda8585db1c9238', 'flavorweave-catalog-package', 'catalog/deep-fried-cod-roasted-potatoes/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_egyptian-koshari_v1', 'rcp_egyptian-koshari', 'egyptian-koshari', 1, 'Egyptian Koshari with Crispy Onions and Garlic-Vinegar Dakka', 'Cairo''s street-food favorite: brown lentils, toasted rice, and elbow macaroni layered under a cumin-spiced tomato sauce, topped with a tangle of shallow-fried crispy onions and splashed with a sharp garlic-vinegar dakka.', 4, 15, 42, 57, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Medium simmer for the lentils; oil at medium (about 325 F) for shallow-frying the onions; covered low for the rice; rolling boil for the pasta; medium simmer for the sauce.', 'Lentils tender but whole; onions deep golden-brown and crisp once drained; rice and pasta tender; sauce thick.', '["simmer","shallow-fry","boil"]', '[]', 'null', '[{"component_id":"lentils","name":"brown lentils","made_in_recipe":true,"store_bought":false,"ingredients":["brown lentils","water","salt"]},{"component_id":"onions","name":"crispy onions","made_in_recipe":true,"store_bought":false,"ingredients":["onions","oil","salt"]},{"component_id":"rice","name":"toasted rice","made_in_recipe":true,"store_bought":false,"ingredients":["rice","onion oil","water"]},{"component_id":"pasta","name":"elbow macaroni","made_in_recipe":true,"store_bought":false,"ingredients":["macaroni","water","salt"]},{"component_id":"sauce","name":"spiced tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["crushed tomatoes","garlic","cumin","coriander","chile flakes","vinegar","sugar"]},{"component_id":"dakka","name":"garlic-vinegar dakka","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","vinegar","water","cumin"]}]', 'published', 'draft', 'global', NULL, '3ec534540a0daf7a7adb81cba0a1d8d55ea09e564e2cbe327f2082b843d66604', 'flavorweave-catalog-package', 'catalog/egyptian-koshari/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ethiopian-beef-tibs_v1', 'rcp_ethiopian-beef-tibs', 'ethiopian-beef-tibs', 1, 'Ethiopian Berbere Beef Tibs', 'Cubed beef quickly sautéed with onion, garlic, ginger, and berbere until deeply spiced and browned, finished with tomato and herbs. Served with rice or greens (injera optional if available).', 4, 15, 25, 40, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium-high to sear beef; medium for onion base; medium-high to finish. No oven. No grill required.', 'Beef cubes browned outside, medium inside (~135–140 F). Onions soft and brick-red with berbere. Tomato melted into the base. Not a long braise. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"berbere-beef","name":"berbere-seasoned beef cubes","made_in_recipe":true,"store_bought":false,"ingredients":["beef sirloin","berbere","kosher salt","black pepper"]},{"component_id":"onion-berbere-base","name":"onion berbere base","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onion","garlic","fresh ginger","berbere","smoked paprika","tomato","neutral oil"]}]', 'published', 'draft', 'global', NULL, '86179e71ae899b80072b9d40d4d1b2d3063c33bde78143edd08e18d76c680168', 'flavorweave-catalog-package', 'catalog/ethiopian-beef-tibs/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_filipino-chicken-adobo_v1', 'rcp_filipino-chicken-adobo', 'filipino-chicken-adobo', 1, 'Filipino Chicken Adobo', 'Bone-in chicken thighs seared until golden, braised in soy sauce, vinegar, smashed garlic, bay leaves, and cracked black pepper, then reduced until the sauce turns glossy and clings to the chicken. Served over jasmine rice with crisp garlic chips and scallions.', 4, 12, 52, 64, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium-low for garlic chips, medium-high sear, low covered braise, medium uncovered reduction. No oven.', 'Skin deep golden and glazed, meat tender and at least 175°F near the bone. Sauce reduced by about half, glossy and clinging. Garlic chips pale gold and crisp. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"garlic-chips","name":"crisp garlic chips","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","neutral oil"]},{"component_id":"chicken-adobo","name":"glazed chicken adobo","made_in_recipe":true,"store_bought":false,"ingredients":["chicken thighs","soy sauce","vinegar","water","brown sugar","smashed garlic","bay leaves","black peppercorns"]},{"component_id":"jasmine-rice-cooked","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'a1fa3c7531a7467bb9c998f6ae965ca01f8c2acc75dfbec8943b4883c30d0196', 'flavorweave-catalog-package', 'catalog/filipino-chicken-adobo/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_filipino-fish-sinigang_v1', 'rcp_filipino-fish-sinigang', 'filipino-fish-sinigang', 1, 'Filipino Fish Sinigang with Tamarind Broth', 'A bright, sour tamarind broth simmered with tomato, onion, daikon, and green beans, then finished by gently poaching chunks of red snapper and wilting bok choy. Served with steamed jasmine rice.', 4, 12, 39, 51, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'High to boil, then a gentle medium-low simmer. The fish poaches below a boil.', 'Daikon translucent and tender; green beans bright and tender-crisp; snapper opaque and just flaking, 145 F; bok choy wilted but green.', '["simmer","poach"]', '[]', 'null', '[{"component_id":"sinigang-broth","name":"tamarind fish sinigang","made_in_recipe":true,"store_bought":false,"ingredients":["water","tamarind paste","tomatoes","onion","ginger","daikon","green beans","red snapper","bok choy","fish sauce","serrano"]},{"component_id":"rice","name":"steamed jasmine rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water"]}]', 'published', 'draft', 'global', NULL, 'cdb0e11c010068f54a6fb08339e711545f1a1ed5042882f5c2a1ba3339110fb4', 'flavorweave-catalog-package', 'catalog/filipino-fish-sinigang/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_french-onion-soup_v1', 'rcp_french-onion-soup', 'french-onion-soup', 1, 'French Onion Soup with Gruyere Toasts and Butter Lettuce Salad', 'Three pounds of onions slowly caramelized in butter until deep mahogany, simmered with beef stock, thyme, and a splash of sherry vinegar, then crowned with a toasted baguette slice and bubbling, browned Gruyere under the broiler. A simple Dijon-dressed butter lettuce salad on the side.', 4, 15, 79, 94, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Medium, then medium-low, to caramelize the onions; medium-low simmer; broiler on high to toast and melt.', 'Onions deep brown and jammy. Cheese melted, bubbling, and browned in spots.', '["saute","simmer","broil"]', '[]', 'null', '[{"component_id":"soup","name":"onion soup","made_in_recipe":true,"store_bought":false,"ingredients":["yellow onions","butter","thyme","bay leaves","flour","beef stock","sherry vinegar","salt","pepper"]},{"component_id":"gratinee","name":"Gruyere toasts","made_in_recipe":true,"store_bought":false,"ingredients":["baguette","gruyere"]},{"component_id":"salad","name":"butter lettuce salad","made_in_recipe":true,"store_bought":false,"ingredients":["butter lettuce","dijon","red wine vinegar","olive oil"]}]', 'published', 'draft', 'global', NULL, '7e7f37cefb5b4844f4f5ab3a5142ee71f10ed3c39a8737e84daa6f481900bb21', 'flavorweave-catalog-package', 'catalog/french-onion-soup/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_garlic-tomato-mussels_v1', 'rcp_garlic-tomato-mussels', 'garlic-tomato-mussels', 1, 'Garlic Tomato Mussels with Grilled Bread', 'Mussels steamed in a garlic and crushed-tomato broth, finished with parsley and lemon, with oil-brushed bread toasted in a skillet.', 4, 15, 13, 28, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium for the onion and garlic, then a 4-minute simmer, then medium-high under a lid for the mussels. Bread toasts over medium-high.', 'Mussels are done when the shells open, usually 4 to 6 minutes. Discard any that stay closed. Do not cook them until they shrink.', '[]', '[]', 'null', '[{"component_id":"tomato-garlic-broth","name":"tomato garlic broth","made_in_recipe":true,"store_bought":false,"note":"Built in the pot from the listed aromatics, canned crushed tomatoes, and dry white wine. Those two store-bought inputs are labeled on the ingredients. There is no separate bottled sauce.","ingredients":["olive oil","onion","garlic","red pepper flakes","crushed tomatoes","dry white wine","kosher salt","black pepper"]}]', 'published', 'draft', 'global', NULL, '2bb5132a5a696df72a5fc27bb26431050fbdb70b21bb1fbc026209aa87c95916', 'flavorweave-catalog-package', 'catalog/garlic-tomato-mussels/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_georgian-adjaruli-khachapuri_v1', 'rcp_georgian-adjaruli-khachapuri', 'georgian-adjaruli-khachapuri', 1, 'Georgian Adjaruli Khachapuri: Cheese Bread Boats with Egg', 'Boat-shaped yeasted breads filled with a molten blend of mozzarella and feta, baked until the crust is burnished, then finished with a soft-baked egg in the center and a pat of butter to swirl in at the table. Served with a cucumber, tomato, and dill salad.', 4, 70, 31, 101, 'involved', 'simple', '5c96a847dece17be968649c3c11b24bd711058ea1c1d8e24db468d59544c5b1f', 'Oven preheated to 475 F with a sheet pan inside, lower-middle rack.', 'Crust deep golden; cheese bubbling; egg white just set and yolk still runny.', '["bake"]', '[]', 'null', '[{"component_id":"dough","name":"yeasted dough","made_in_recipe":true,"store_bought":false,"ingredients":["flour","instant yeast","sugar","water","olive oil","salt"]},{"component_id":"filling","name":"cheese filling with egg and butter","made_in_recipe":true,"store_bought":false,"ingredients":["mozzarella","feta","eggs","butter"]},{"component_id":"salad","name":"cucumber-tomato-dill salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumbers","tomatoes","red onion","dill","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, '797340f8dad1033cda161cb098927520eccdea1d88634b83fd6c5912714b64fd', 'flavorweave-catalog-package', 'catalog/georgian-adjaruli-khachapuri/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ghanaian-red-red-plantains_v1', 'rcp_ghanaian-red-red-plantains', 'ghanaian-red-red-plantains', 1, 'Ghanaian Red-Red: Black-Eyed Pea Stew with Spiced Roasted Plantains', 'Black-eyed peas simmered in a vivid red stew of red palm oil, tomato, onion, ginger, garlic, and Scotch bonnet, served with oven-roasted ripe plantains tossed in ginger and cayenne (a baked take on kelewele).', 4, 15, 30, 45, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven preheated to 425 F for the plantains. Medium sauté; medium-low simmer.', 'Stew thick and glossy with a little red oil on top; peas creamy. Plantains caramelized at the edges and soft through.', '["saute","simmer","roast"]', '[]', 'null', '[{"component_id":"stew","name":"black-eyed pea red stew","made_in_recipe":true,"store_bought":false,"ingredients":["black-eyed peas","red palm oil","onion","crushed tomatoes","tomato paste","ginger","garlic","Scotch bonnet","water","salt"]},{"component_id":"plantains","name":"spiced roasted plantains","made_in_recipe":true,"store_bought":false,"ingredients":["ripe plantains","ginger","cayenne","oil","salt"]}]', 'published', 'draft', 'global', NULL, '803aba54eb58aa3fcf1f158be6669fdaccdb48d3afdc1fd3cd6e4122ed670113', 'flavorweave-catalog-package', 'catalog/ghanaian-red-red-plantains/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ginger-glazed-tempeh-plate_v1', 'rcp_ginger-glazed-tempeh-plate', 'ginger-glazed-tempeh-plate', 1, 'Ginger-Glazed Tempeh with Broccolini', 'Sliced tempeh pan-seared then glazed with ginger, garlic, tamari, and maple, plated with blistered broccolini and rice. No peanut.', 4, 15, 20, 35, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Medium for tempeh sear; medium-high for broccolini; medium for glaze. No oven required.', 'Tempeh deep golden and coated in syrupy ginger-maple glaze. Broccolini tender-crisp with blistered tips. Rice hot. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"ginger-maple-tamari-glaze","name":"ginger-maple tamari glaze","made_in_recipe":true,"store_bought":false,"ingredients":["tamari","maple syrup","fresh ginger","garlic","rice vinegar","water"]},{"component_id":"seared-tempeh","name":"seared glazed tempeh","made_in_recipe":true,"store_bought":false,"ingredients":["tempeh","ginger-maple tamari glaze","neutral oil"]}]', 'published', 'draft', 'global', NULL, '90e176c40469f7f0c01ae93e1a52a4974e5793d7e5671f5357fa60bcde368dea', 'flavorweave-catalog-package', 'catalog/ginger-glazed-tempeh-plate/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ginger-scallion-fish-packets_v1', 'rcp_ginger-scallion-fish-packets', 'ginger-scallion-fish-packets', 1, 'Ginger Scallion Fish Packets', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["fish","finfish","dairy-free"]', 'null', '[]', 'retired', 'published', 'global', NULL, 'cdf2e005363a18ba91896bf56da4ed2a1d3bb14e1a506a8300c0e734956eba99', 'flavorweave-legacy-catalog-package', 'catalog/ginger-scallion-fish-packets/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_ginger-scallion-fish-packets_v2', 'rcp_ginger-scallion-fish-packets', 'ginger-scallion-fish-packets', 2, 'Ginger Scallion Fish Packets', 'Foil packets of white fish and halved bok choy with ginger, scallion, and soy, baked until the fish flakes, served with rice.', 4, 15, 20, 35, 'easy', 'simple', 'babd7dabd7743db6960cd85230f4a7cab0c70b57bc8930feeaf69b78e19cca59', 'Oven 400 F for the packets. Rice simmers, covered, on the stove and overlaps the bake.', 'Fish flakes easily and is opaque in the center, 18 to 20 minutes at 400 F. Bok choy is tender. Rice is tender and the water is absorbed. Not a rare fillet and not a sear.', '["oven","stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'bb8cb1a88efa57b28918f88a7e127352951dddeec9de0580be44e35e6e62cd51', 'flavorweave-legacy-audit-draft', 'catalog/ginger-scallion-fish-packets/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_glazed-turkey-meatloaf_v1', 'rcp_glazed-turkey-meatloaf', 'glazed-turkey-meatloaf', 1, 'Glazed Turkey Meatloaf with Lemon Green Beans', 'A tender, juicy turkey meatloaf shaped free-form on a sheet pan and brushed with a tangy ketchup, brown sugar, and Dijon glaze that bakes into a sticky lacquer. Green beans roast on the same pan and get a squeeze of lemon and parsley.', 4, 15, 68, 83, 'easy', 'standard', '699d309589d22307c254526b29a51d18b9e88d2063d14aeade9921f0eab2c506', 'Oven preheated to 375 F, middle rack.', 'Meatloaf 165 F in the center with a sticky, darkened glaze; green beans tender with browned spots.', '["bake","roast"]', '[]', 'null', '[{"component_id":"meatloaf","name":"turkey meatloaf","made_in_recipe":true,"store_bought":false,"ingredients":["ground turkey","panko","eggs","milk","onion","garlic","soy sauce","thyme","salt","pepper"]},{"component_id":"glaze","name":"ketchup glaze","made_in_recipe":true,"store_bought":false,"ingredients":["ketchup","brown sugar","Dijon"]},{"component_id":"beans","name":"roasted lemon green beans","made_in_recipe":true,"store_bought":false,"ingredients":["green beans","olive oil","lemon","parsley"]}]', 'published', 'draft', 'global', NULL, '8fbb1e14a942c95ad1a8293a7705913b93088b58f08db5043838182ef134e1d7', 'flavorweave-catalog-package', 'catalog/glazed-turkey-meatloaf/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_gochujang-grilled-flank-steak_v1', 'rcp_gochujang-grilled-flank-steak', 'gochujang-grilled-flank-steak', 1, 'Gochujang Grilled Flank Steak', 'Thin-sliced grilled flank steak in a short gochujang marinade, with a sharp cucumber and scallion salad.', 4, 25, 25, 50, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Direct grill heat, about 450–500°F.', '130–135°F in the center for medium-rare, then a 5-minute rest. Slice against the grain.', '[]', '[]', 'null', '[{"component_id":"gochujang-marinade","name":"gochujang marinade","made_in_recipe":true,"store_bought":false,"ingredients":["gochujang","soy sauce","rice vinegar","toasted sesame oil","brown sugar","garlic","fresh ginger","black pepper","scallions"]},{"component_id":"scallion-cucumber-salad","name":"scallion cucumber salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","scallions","rice vinegar","toasted sesame oil","kosher salt","sesame seeds"]}]', 'published', 'draft', 'global', NULL, '0cce02e42a32c06722cdbf79b36cdb69513a621814e4a277772182f9e02fd495', 'flavorweave-catalog-package', 'catalog/gochujang-grilled-flank-steak/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_greek-chicken-souvlaki_v1', 'rcp_greek-chicken-souvlaki', 'greek-chicken-souvlaki', 1, 'Greek Chicken Souvlaki with Cucumber Salad', 'Lemon-oregano marinated chicken thigh skewers grilled or broiled, served with a dairy-free cucumber-tomato-dill salad.', 4, 15, 35, 50, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Grill or grill pan medium-high, or oven broiler on high 6 inches from element. Broiler preheat 5 minutes overlaps skewer threading.', 'Chicken 165 F in the thickest piece, browned in spots. Salad crisp, not watery. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lemon-oregano-marinade","name":"lemon-oregano marinade","made_in_recipe":true,"store_bought":false,"ingredients":["olive oil","lemon juice","garlic","dried oregano","kosher salt","black pepper"]},{"component_id":"cucumber-tomato-salad","name":"cucumber tomato salad","made_in_recipe":true,"store_bought":false,"ingredients":["English cucumber","cherry tomatoes","red onion","fresh dill","lemon juice","olive oil","kosher salt"]}]', 'published', 'draft', 'global', NULL, 'ea512eba31dd1de36350eeb86586cd600a413f355b35bb5c24d788d3dc8c5b62', 'flavorweave-catalog-package', 'catalog/greek-chicken-souvlaki/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_greek-gemista-stuffed-vegetables_v1', 'rcp_greek-gemista-stuffed-vegetables', 'greek-gemista-stuffed-vegetables', 1, 'Greek Gemista: Herb-and-Rice Stuffed Tomatoes and Peppers', 'Big tomatoes and bell peppers hollowed out and filled with rice simmered in their own tomato pulp with onion, garlic, parsley, mint, and oregano, then slow-baked with olive oil and potato wedges until the vegetables slump, the rice is tender, and the tops and potatoes are caramelized.', 4, 25, 85, 110, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Oven preheated to 375 F. Covered bake, then uncovered to caramelize.', 'Rice fully tender all the way through (taste one); peppers soft and slumped; tomato caps and potato edges browned; pan juices mostly reduced and syrupy.', '["saute","simmer","bake"]', '[]', 'null', '[{"component_id":"filling","name":"herbed tomato rice filling","made_in_recipe":true,"store_bought":false,"ingredients":["medium-grain rice","tomato pulp","onion","garlic","tomato paste","parsley","mint","oregano","sugar","olive oil","salt"]},{"component_id":"vegetables","name":"stuffed tomatoes and peppers with potatoes","made_in_recipe":true,"store_bought":false,"ingredients":["tomatoes","bell peppers","potatoes","water","olive oil"]}]', 'published', 'draft', 'global', NULL, '19d60fb76d36cac19794de466e5fde7e1c360093e6020d7c70e4cbd76ab20530', 'flavorweave-catalog-package', 'catalog/greek-gemista-stuffed-vegetables/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_greek-spanakopita_v1', 'rcp_greek-spanakopita', 'greek-spanakopita', 1, 'Greek Spanakopita Pan Pie with Cucumber-Tomato Salad', 'A golden, flaky pan pie of olive-oil-brushed phyllo layered around a spinach, feta, scallion, dill, and parsley filling with a hint of nutmeg, baked until shatteringly crisp. Served with a sharp cucumber, tomato, and oregano salad.', 4, 35, 61, 96, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Medium to soften the onions; 375 F oven to bake.', 'Phyllo deep golden and crisp on top and bottom; filling set (160 F in the center).', '["saute","bake"]', '[]', 'null', '[{"component_id":"filling","name":"spinach and feta filling","made_in_recipe":true,"store_bought":false,"ingredients":["spinach","feta","eggs","scallions","onion","dill","parsley","nutmeg","pepper"]},{"component_id":"pastry","name":"phyllo layers","made_in_recipe":false,"store_bought":true,"ingredients":["phyllo","olive oil"]},{"component_id":"salad","name":"cucumber-tomato salad","made_in_recipe":true,"store_bought":false,"ingredients":["cucumber","tomatoes","red wine vinegar","oregano","olive oil","salt"]}]', 'published', 'draft', 'global', NULL, '776b1324d5bed9e9b48572801310aee2ee85a26bc22cdf690a315c97d28c53dc', 'flavorweave-catalog-package', 'catalog/greek-spanakopita/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_grilled-mackerel-fennel-orange_v1', 'rcp_grilled-mackerel-fennel-orange', 'grilled-mackerel-fennel-orange', 1, 'Grilled Mackerel with Fennel and Orange', 'Whole mackerel grilled with fennel wedges and an orange-parsley relish. Olive oil, no butter.', 4, 15, 18, 33, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'A hot grill, fish over direct heat, fennel over a slightly cooler spot.', 'Mackerel opaque at the bone and 145 F in the thickest part. Fennel tender with grill marks, still a little firm.', '["grill"]', '[]', 'null', '[{"component_id":"relish","name":"orange parsley relish","made_in_recipe":true,"store_bought":false,"ingredients":["orange","parsley","garlic","red pepper flakes","olive oil"]}]', 'published', 'draft', 'global', NULL, '687447237be49680ffb21ea4fbeab86811b7ced075291c0bf5a0366eea331a56', 'flavorweave-catalog-package', 'catalog/grilled-mackerel-fennel-orange/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_grilled-mahi-mahi-mango-salsa_v1', 'rcp_grilled-mahi-mahi-mango-salsa', 'grilled-mahi-mahi-mango-salsa', 1, 'Grilled Mahi-Mahi with Mango-Jalapeño Salsa and Lime Rice', 'Chile-lime rubbed mahi-mahi fillets grilled until just flaky, topped with a juicy mango, red pepper, red onion, jalapeño, and cilantro salsa, and served over cilantro-lime jasmine rice.', 4, 15, 11, 26, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'Gas grill or grill pan preheated to medium-high, clean oiled grates. Covered low simmer for the rice.', 'Fish opaque and flaking, 137 to 145 F in the center, with grill marks.', '["grill","simmer"]', '[]', 'null', '[{"component_id":"fish","name":"chile-lime grilled mahi-mahi","made_in_recipe":true,"store_bought":false,"ingredients":["mahi-mahi","chili powder","cumin","lime","oil","salt"]},{"component_id":"salsa","name":"mango-jalapeño salsa","made_in_recipe":true,"store_bought":false,"ingredients":["mango","red bell pepper","red onion","jalapeño","cilantro","lime","salt"]},{"component_id":"rice","name":"cilantro-lime rice","made_in_recipe":true,"store_bought":false,"ingredients":["jasmine rice","water","lime","cilantro","salt"]}]', 'published', 'draft', 'global', NULL, 'ee390ede39f810988a730122aca2da8bdae3228f46a000cc3571d31df08f852a', 'flavorweave-catalog-package', 'catalog/grilled-mahi-mahi-mango-salsa/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_grilled-peach-burrito-bowl_v1', 'rcp_grilled-peach-burrito-bowl', 'grilled-peach-burrito-bowl', 1, 'Grilled Peach Burrito Bowl', NULL, 4, 15, 25, 40, NULL, NULL, NULL, NULL, NULL, '["stovetop"]', '["plant","dairy-free","bowl"]', 'null', '[]', 'retired', 'published', 'global', NULL, 'aeed2d371fdc5be0185bbbc11ccca84fe731c082f811bedb10e577c6b4743232', 'flavorweave-legacy-catalog-package', 'catalog/grilled-peach-burrito-bowl/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_grilled-peach-burrito-bowl_v2', 'rcp_grilled-peach-burrito-bowl', 'grilled-peach-burrito-bowl', 2, 'Grilled Peach Burrito Bowl', 'Grilled peach slices over lime-seasoned rice and cumin black beans, with pickled red onion and cilantro.', 4, 15, 10, 25, 'moderate', 'simple', 'fff648ac7b6240cd1d7f5fe3af9d8fd777f0aa0b0a9735e530ee04a1e367da2d', 'none', 'Peach slices charred at the edges and still holding their shape, not collapsed. Beans heated through. Rice warm.', '["grill","stovetop"]', '["plant","dairy-free"]', '{"pickled red onion":"Use store-bought. A quick pickle is not specified here because v1 gave no brine.","rice":"Start from 3 cups cooked rice. Cooking rice from raw is extra time and is not inside the 25 minutes."}', '[]', 'published', 'unpublished_curator_draft', 'global', NULL, '298896f8aab18c9b70fa090749a9fa10235ccc759926c40a6a595c2eed2e2d33', 'flavorweave-legacy-catalog-package', 'catalog/grilled-peach-burrito-bowl/v2.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_grilled-swordfish-olive-caper_v1', 'rcp_grilled-swordfish-olive-caper', 'grilled-swordfish-olive-caper', 1, 'Grilled Swordfish with Olive-Caper Relish', 'Thick grilled swordfish steaks and grilled fennel, with a chopped olive, caper, and anchovy relish.', 4, 18, 28, 46, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Direct grill heat, about 450-500 F.', 'Pull swordfish at 130-135 F in the center, then rest 3 minutes. The edge should be opaque and the very center just losing its translucence, flaking under pressure, not chalky. 145 F is the more conservative seafood temperature and will be drier; add about 1 minute per side for that target. The written target is 130-135 F. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"olive-caper-relish","name":"olive-caper relish","made_in_recipe":true,"store_bought":false,"ingredients":["pitted green olives","capers","anchovy fillets","garlic","lemon","fresh parsley","olive oil","kosher salt","red pepper flakes"]}]', 'published', 'draft', 'global', NULL, '14840a0829d278d892144f493158e41bd0c731311a72d968d877fd87117356f0', 'flavorweave-catalog-package', 'catalog/grilled-swordfish-olive-caper/v1.json', '2026-10-04T00:00:00.000Z');
