INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lebanese-samke-harra-bulgur_v1', 'rcp_lebanese-samke-harra-bulgur', 'lebanese-samke-harra-bulgur', 1, 'Lebanese Samke Harra: Spicy Tahini-Baked Cod with Bulgur Pilaf', 'Cod fillets spread with a sizzling garlic, red chile, Aleppo pepper, and cilantro topping, blanketed in lemony tahini sauce, and baked until bubbling and just flaking. Served over a toasty onion and tomato bulgur pilaf.', 4, 15, 34, 49, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Oven preheated to 400 F, middle rack. Medium skillet for the harra topping. Covered low simmer for the bulgur.', 'Tahini sauce bubbling at the edges and lightly golden in spots; cod opaque, flaking, and 145 F in the thickest part. Bulgur tender and separate with no liquid left.', '["bake","saute","simmer"]', '[]', 'null', '[{"component_id":"harra","name":"garlic-chile-cilantro harra","made_in_recipe":true,"store_bought":false,"ingredients":["garlic","red chiles","Aleppo pepper","cumin","cilantro","olive oil"]},{"component_id":"tahini-sauce","name":"lemon tahini sauce","made_in_recipe":true,"store_bought":false,"ingredients":["tahini","lemon","garlic","water","salt"]},{"component_id":"fish","name":"baked cod","made_in_recipe":true,"store_bought":false,"ingredients":["cod","salt"]},{"component_id":"bulgur","name":"onion-tomato bulgur pilaf","made_in_recipe":true,"store_bought":false,"ingredients":["coarse bulgur","onion","tomato paste","water","olive oil"]}]', 'published', 'draft', 'global', NULL, 'e7e4121babf163c590649a25268894dceb50d0a56744efd1b17dd9896d94a619', 'flavorweave-catalog-package', 'catalog/lebanese-samke-harra-bulgur/v1.json', '2026-10-04T00:00:00.000Z');
