INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lemon-pea-risotto_v1', 'rcp_lemon-pea-risotto', 'lemon-pea-risotto', 1, 'Lemon Pea Risotto', 'Arborio rice stirred with hot vegetable stock until creamy, finished with peas, lemon, butter, and microbial-rennet Parmesan.', 4, 12, 28, 40, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'Stock held at a bare simmer. Risotto pot over medium for shallot and toast, then medium to medium-low while ladling. Finish off heat.', 'Rice al dente with creamy starch suspension. Peas hot and bright. Spreads slowly on a plate. Lemon bright, not bitter from too much pith. kitchen_tested is false.', '[]', '[]', 'null', '[{"component_id":"lemon-parmesan-finish","name":"lemon-Parmesan finish","made_in_recipe":true,"store_bought":false,"ingredients":["unsalted butter","vegetarian Parmesan","lemon zest","lemon juice","black pepper","kosher salt","fresh parsley","frozen peas"]}]', 'published', 'draft', 'global', NULL, 'f56ca409b3ca8384c0e39bc875a7aa41a0c972b7a9091f9339f9dc7e80676a7e', 'flavorweave-catalog-package', 'catalog/lemon-pea-risotto/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_lentil-stuffed-cabbage_v1', 'rcp_lentil-stuffed-cabbage', 'lentil-stuffed-cabbage', 1, 'Lentil-Stuffed Cabbage with Tomato Sauce', 'Cabbage leaves rolled around brown lentils and parcooked rice, baked in a tomato sauce made from crushed tomatoes.', 4, 35, 106, 141, 'involved', 'standard', '66a97cd2f60ec8784b979b25d5a0627d6bd9f3733e5319e7862835bd2d685c4d', 'Stove for the lentils, rice, filling, and sauce. Oven 375 F for the covered bake, then uncovered.', 'Lentils are simmered only until tender with a bite, then finish in the oven. Rolls bake 40 minutes covered and 10 minutes uncovered at 375 F until the center filling is hot and steaming and the leaf edges show browned spots.', '[]', '[]', 'null', '[{"component_id":"lentil-rice-filling","name":"lentil-rice filling","made_in_recipe":true,"store_bought":false,"ingredients":["brown lentils","long-grain white rice","yellow onion","garlic","olive oil","kosher salt","black pepper","sweet paprika","fresh parsley"]},{"component_id":"tomato-sauce","name":"tomato sauce","made_in_recipe":true,"store_bought":false,"ingredients":["crushed tomatoes","yellow onion","garlic","olive oil","water","red wine vinegar","brown sugar","kosher salt","green cabbage"]}]', 'published', 'draft', 'global', NULL, 'dd84c30742df80e54d6790c21118b42301ed5c06fd62dfc4e9cff5fe5b0336ff', 'flavorweave-catalog-package', 'catalog/lentil-stuffed-cabbage/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_linguine-with-clams_v1', 'rcp_linguine-with-clams', 'linguine-with-clams', 1, 'Linguine with Clams', 'Littleneck clams steamed open in garlic and white wine, tossed with linguine, parsley, and lemon. No cheese and no butter.', 4, 15, 18, 33, 'moderate', 'standard', '08ceede8e31d0536861737ed10ce02ecde3d242f006e7c41e7d6c307f16cc5ec', 'A large pot of boiling water for the pasta. A 12-inch skillet or wide pot over medium for the clams.', 'Pasta tender with a slight bite. Clams open. Any clam that stays shut is discarded. Sauce glossy from the clam liquor and olive oil, not creamy.', '["stovetop"]', '[]', 'null', '[]', 'published', 'draft', 'global', NULL, 'c0e654c2983e420a18838d4d3f67bf08edc2e529f11a202ee688f88cd430515c', 'flavorweave-catalog-package', 'catalog/linguine-with-clams/v1.json', '2026-10-04T00:00:00.000Z');
INSERT OR REPLACE INTO catalog_version (recipe_version_id, recipe_id, dish_id, version_number, title, description, base_servings, prep_minutes, cook_minutes, total_minutes, effort_level, ingredient_complexity, classification_hash, heat, doneness, methods_json, dietary_tags_json, substitutions_json, components_json, publication_status, artifact_publication_status, visibility, household_id, content_hash, source_contract, source_path, created_at) VALUES ('rv_malaysian-curry-laksa_v1', 'rcp_malaysian-curry-laksa', 'malaysian-curry-laksa', 1, 'Malaysian Curry Laksa with Shrimp', 'A rich, spicy coconut noodle soup: a homemade paste of shallots, lemongrass, ginger, garlic, dried chiles, turmeric, and shrimp paste, sizzled in oil and simmered with coconut milk and stock, then poured over rice vermicelli and shrimp and piled with bean sprouts, cucumber, mint, and lime.', 4, 25, 28, 53, 'involved', 'adventurous', '6ee7bb37273cbc12eff6d5be73cdb6c79a88a65cdfe5ea686de96c0b7a43a78d', 'Medium to cook the paste until the oil separates; medium-low simmer; gentle simmer to poach the shrimp; boil for the noodles.', 'Paste dark and fragrant with oil separating; broth creamy and orange-red; shrimp pink and just opaque (120 to 125 F).', '["saute","simmer","boil"]', '[]', 'null', '[{"component_id":"paste","name":"laksa paste","made_in_recipe":true,"store_bought":false,"ingredients":["shallots","garlic","ginger","lemongrass","dried chiles","turmeric","coriander","shrimp paste","oil"]},{"component_id":"broth","name":"coconut laksa broth with shrimp","made_in_recipe":true,"store_bought":false,"ingredients":["coconut milk","chicken stock","fish sauce","brown sugar","shrimp"]},{"component_id":"noodles","name":"rice vermicelli","made_in_recipe":true,"store_bought":false,"ingredients":["rice vermicelli","water"]},{"component_id":"garnish","name":"fresh garnishes","made_in_recipe":true,"store_bought":false,"ingredients":["bean sprouts","cucumber","mint","limes"]}]', 'published', 'draft', 'global', NULL, '664e134dd4a46fb521e61c76415dabd9835c4618031847d75a0d248f53051ccc', 'flavorweave-catalog-package', 'catalog/malaysian-curry-laksa/v1.json', '2026-10-04T00:00:00.000Z');
